(7182468, 1103322, 136989, '<td valign="top">Love it!  Great lighting.  The balance of shadows and sinister facial expressions is awesome. My favorite in this challenge.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1082013" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/135000-139999/136989/120/Copyrighted_Image_Reuse_Prohibited_1082013.jpg"/></a></td>', 'Love it!  Great lighting.  The balance of shadows and sinister facial expressions is awesome. My favorite in this challenge.', '2014-02-27 23:34:19.000000', NULL, 1),
(7182471, 1103561, 11769, '<td valign="top">And be a nuisance</td>', 'And be a nuisance', '2014-02-27 23:46:10.000000', NULL, 1),
