(7182473, 1103352, 11769, '<td valign="top">nice tones</td>', 'nice tones', '2014-02-27 23:46:59.000000', NULL, 1),
(7182474, 1103428, 11769, '<td valign="top">everyone needs their pole</td>', 'everyone needs their pole', '2014-02-27 23:47:23.000000', NULL, 1),
(7182475, 1103666, 11769, '<td valign="top">great photo</td>', 'great photo', '2014-02-27 23:48:11.000000', NULL, 1),
(7182904, 1103010, 121111, '<td valign="top">excellent !</td>', 'excellent !', '2014-02-28 15:17:31.000000', NULL, 1),
(7182918, 1103428, 173844, '<td valign="top">The heavy grain works well in this stark image.  Though I haven''t figured out the meaning in this picture, I''m sure it''s just escaped me because the scene seems heavy with intimation.  That bird pointing elsewhere to the arriving bird is a delicious capture. Very satisfying.</td>', 'The heavy grain works well in this stark image.  Though I haven''t figured out the meaning in this picture, I''m sure it''s just escaped me because the scene seems heavy with intimation.  That bird pointing elsewhere to the arriving bird is a delicious capture. Very satisfying.', '2014-02-28 15:31:06.000000', NULL, 1),
(7182922, 1103668, 173844, '<td valign="top">High class political satire.  Perfect depth of field, balanced composition.  A well-put-together morsel, maybe a bit calorie rich.</td>', 'High class political satire.  Perfect depth of field, balanced composition.  A well-put-together morsel, maybe a bit calorie rich.', '2014-02-28 15:37:32.000000', NULL, 1),
(7182925, 1103520, 173844, '<td valign="top">Beautifully captures the mood of local (I''m guessing) politics.  The skewed angle suggests informality.  The smiling faces and Canadian flag suggest a lack of vein-throbbing extremists.  Lucky you.</td>', 'Beautifully captures the mood of local (I''m guessing) politics.  The skewed angle suggests informality.  The smiling faces and Canadian flag suggest a lack of vein-throbbing extremists.  Lucky you.', '2014-02-28 15:48:17.000000', NULL, 1),
(7182927, 1103382, 173844, '<td valign="top">I like this gentleman''s direct, if watery, gaze.  He''s right out there, expressing himself, filling the frame.  I also appreciate the hint of an American flag gripped in his right hand.  Black and white works well here.  And if he feels like a snack later on, that ''LEGALIZE'' sign looks like it''s printed on the cover of some Jiffy Pop.</td>', 'I like this gentleman''s direct, if watery, gaze.  He''s right out there, expressing himself, filling the frame.  I also appreciate the hint of an American flag gripped in his right hand.  Black and white works well here.  And if he feels like a snack later on, that ''LEGALIZE'' sign looks like it''s printed on the cover of some Jiffy Pop.', '2014-02-28 15:58:25.000000', NULL, 1),
(7182932, 1103561, 173844, '<td valign="top">Sharp political commentary.  Wonderful juxtaposition of this young child and the whole looming security apparatus.  Furthermore, the wires ensnare and ensnarl him.  I remember when we used to talk about the repressive spying of the commies on their own citizens.  Good to see that the ecumenical spirit of democracy has embraced its former bete noire.</td>', 'Sharp political commentary.  Wonderful juxtaposition of this young child and the whole looming security apparatus.  Furthermore, the wires ensnare and ensnarl him.  I remember when we used to talk about the repressive spying of the commies on their own citizens.  Good to see that the ecumenical spirit of democracy has embraced its former bete noire.', '2014-02-28 16:11:35.000000', NULL, 1),
(7183055, 1103672, 150277, '<td valign="top">Very striking.</td>', 'Very striking.', '2014-02-28 22:54:42.000000', NULL, 1),
(7183056, 1103668, 150277, '<td valign="top">Neat.  I like the originality and the blurred items in the background.</td>', 'Neat.  I like the originality and the blurred items in the background.', '2014-02-28 22:55:37.000000', NULL, 1),
